import random
rng = random.Random(5)

# True rule is y = 2x, but every measurement has noise.
def sample(n):
    return [(x, 2 * x + rng.gauss(0, 3)) for x in (rng.uniform(0, 10) for _ in range(n))]

train, valid = sample(8), sample(30)

def mse(pred, data):
    return sum((pred(x) - y) ** 2 for x, y in data) / len(data)

# Model A: memoriser - copies the answer of the nearest training point
def memoriser(x):
    return min(train, key=lambda p: abs(p[0] - x))[1]

# Model B: simple line y = w*x, fitted by least squares
w = sum(x * y for x, y in train) / sum(x * x for x, _ in train)
def line(x):
    return w * x

print("fitted slope w =", round(w, 2), "(truth 2)")
print("model     train_error  valid_error")
for name, f in (("memoriser", memoriser), ("line", line)):
    print(f"{name:9s} {mse(f, train):10.2f} {mse(f, valid):12.2f}")
print("A big gap (train near 0, valid large) is the sign of overfitting.")
